public class Caverphone_caverphone_TriageGen2Test {

    private Caverphone caverphone;

    @Before
    public void setUp() {
        caverphone = new Caverphone();
    }





    @Test
    public void testCaverphone_NonAlphaCharacters() {
        // Should remove non-A-Z and handle lowercase
        // "A1!b" -> "ab" -> "Ab" -> "Ab" -> "A" (if a is vowel) -> "A" + 10 1s
        // Let's trace "A1!b": 
        // 1. lowercase: "a1!b" 
        // 2. remove non-a-z: "ab"
        // 2.5. remove final e: "ab"
        // 4. replacements: "a" -> "A", "b" -> "p" -> "p" (no, b becomes p)
        // Result should be "Ap1111111111" -> substring(0,10) "Ap11111111"
        // Actually, let's use a simpler known case if possible or just verify behavior
        String result = caverphone.caverphone("A1!b");
        assertTrue(result.startsWith("Ap"));
    }














































}

